class Solution:
    def subsets(self, nums):
        res, path = [], []

        def dfs(i):
            if i == len(nums):
                res.append(path[:])
                return
            path.append(nums[i])      # include nums[i]
            dfs(i + 1)
            path.pop()                # exclude nums[i]
            dfs(i + 1)

        dfs(0)
        return res

