class Solution:
    def combinationSum(self, candidates, target):
        cand = sorted(candidates)
        res, path = [], []

        def dfs(start, remain):
            if remain == 0:
                res.append(path[:])
                return
            for j in range(start, len(cand)):
                if cand[j] > remain:
                    break                  # sorted: nothing later fits either
                path.append(cand[j])
                dfs(j, remain - cand[j])   # j, not j+1: reuse allowed
                path.pop()

        dfs(0, target)
        return res

