class Solution:
    def minCostConnectPoints(self, points):
        n = len(points)
        INF = float("inf")
        best = [INF] * n          # cheapest edge from the tree to each outside point
        best[0] = 0
        in_tree = [False] * n
        total = 0
        for _ in range(n):
            u, bu = -1, INF
            for i in range(n):
                if not in_tree[i] and best[i] < bu:
                    u, bu = i, best[i]
            in_tree[u] = True
            total += bu
            ux, uy = points[u]
            for v in range(n):
                if not in_tree[v]:
                    d = abs(ux - points[v][0]) + abs(uy - points[v][1])
                    if d < best[v]:
                        best[v] = d
        return total

