from collections import deque

class Solution:
    def openLock(self, deadends, target):
        seen = set(deadends)                 # never step onto a deadend
        if "0000" in seen:
            return -1
        seen.add("0000")
        q = deque([("0000", 0)])
        while q:
            state, moves = q.popleft()
            if state == target:
                return moves
            for i in range(4):
                d = int(state[i])
                for nd in ((d + 1) % 10, (d - 1) % 10):
                    nxt = state[:i] + str(nd) + state[i + 1:]
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append((nxt, moves + 1))
        return -1

