find-the-city-with-the-smallest-number-o.solution:
class Solution:
    def findTheCity(self, n, edges, distanceThreshold):
        INF = float("inf")
        d = [[INF] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 0
        for a, b, w in edges:
            d[a][b] = d[b][a] = w
        for k in range(n):                       # Floyd-Warshall: allow k as an intermediate stop
            dk = d[k]
            for i in range(n):
                dik = d[i][k]
                if dik == INF:
                    continue
                di = d[i]
                for j in range(n):
                    if dik + dk[j] < di[j]:
                        di[j] = dik + dk[j]
        best_city, best_count = -1, n + 1
        for i in range(n):
            count = sum(1 for j in range(n) if j != i and d[i][j] <= distanceThreshold)
            if count <= best_count:              # <= keeps the largest index on ties
                best_city, best_count = i, count
        return best_city

